// Колония ИЗ НАШИХ АССЕТОВ. Решение владельца: чужие наборы не используются.
// Ландшафт - один сплошной меш с ярусами (правило: земля не тайлится
// кусками, иначе поднос с ячейками), текстура земли испечена из наших же
// рисованных тайлов (design/tools/bake-ground-tex.py).
// Ярусы: Low=0, High=+1, Deep=-1 (чаша карьера) - перенос из SceneBuilder3D.
// Посадка моделей лучом сверху вниз: не парят и не тонут.
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Profiling;

public static class ColonyOursBuilder
{
    // Мир вырос вместе с колонией: после дублирования жилья и укрупнения
    // складов застройка заняла ±23 м, и декор выдавливало за край карты.
    private const float KrayRadius = 35f;  // радиус, с которого земля уходит к горизонту
    private const float World = 62f;      // сторона участка колонии, метры

    /// <summary>
    /// Разброс колонии. Замер 2026-08-16: при 1.0 постройки физически не
    /// помещались в свои зоны — разводка расталкивала, зажим зоны возвращал
    /// обратно, и цикл не сходился (75 пересечений после 80 проходов).
    /// Множитель разносит центры зон, площадки и стартовые позиции, НЕ трогая
    /// размеры самих построек: меняется плотность застройки, а не масштаб.
    /// </summary>
    /// Снижен с 1.35 после снимка 2026-08-16: при 1.35 разводка сходилась, но
    /// колония читалась россыпью предметов на пустой равнине. Township держит
    /// квартал плотным, воздух дают проходы, а не гектары грунта между домами.
    /// Снижен до 0.95 после того, как масштабы построек пришли в норму:
    /// объекты уменьшились вдвое, и прежний разброс развел колонию по
    /// пустой равнине. Плотность держится расстоянием, а не размером.
    // Разброс снят. Он был костылём эпохи, когда позиции подбирались на
    // глаз: множитель поверх координат делал числа в раскладке неточными,
    // а доктрина требует проверяемых расстояний в клетках.
    private const float Spread = 1.0f;

    /// <summary>
    /// СТЯЖКА КЛАСТЕРОВ, круг 6. Пункты 1, 3 и 11 (тяжесть 1, три оценщика
    /// независимо): «голый грунт 86.3% при цели ≤30%», «стянуть постройки
    /// левой и правой групп ближе друг к другу и к центру», «карьер стоит
    /// через пустое поле от промзоны».
    ///
    /// Почему это сдвиг зон, а не масштаб и не новые модели. Кадр наводится
    /// автоподбором (VpisatKadr): дистанция берётся минимальная, при которой
    /// все восемь углов габарита КАЖДОЙ постройки лежат внутри |u|,|v| ≤ 0.98.
    /// Значит доля застройки в кадре — это ровно отношение экранного размаха
    /// колонии к кадру, и уменьшить её нечем, кроме как уменьшить размах.
    ///
    /// ЗАМЕР до правки (проекция раскладки при азимуте -50, наклоне 44,
    /// поле зрения 32): кромки кадра держат ЧЕТЫРЕ разных кластера —
    /// лёд (верх, v +0.97), космопорт (низ, v -0.96), жильё (лево, u -0.94),
    /// карьер (право, u +0.90). Колония — крест с четырьмя концами, и
    /// дистанция вписывания 69-72 м держится всеми четырьмя сразу. Стянуть
    /// один конец бесполезно: кадр удержит любой из трёх других.
    ///
    /// Экранные оси на этом азимуте: вправо = (0.766, 0.643), вверх =
    /// (-0.643, 0.766). Сдвиги подобраны так, чтобы каждый конец шёл к центру
    /// ПО СВОЕЙ экранной оси:
    ///   космопорт (-1.0, +3.0) — вверх по экрану на 2.9 м; он же уходит на
    ///     1.2 клетки дальше от зрителя (пункт 10, тяжесть 2);
    ///   жильё     (+1.5, +1.5) — вправо по экрану на 2.1 м; упирается в
    ///     купол-героя, зазор до него остаётся 0.8 м;
    ///   лёд       (+2.5, -1.5) — вниз по экрану на 2.7 м;
    ///   карьер    (-1.5, -2.0) — влево по экрану на 2.4 м;
    ///   промзона и центр не двигаются: промзона стоит вплотную к куполу
    ///     (0.45 м) и любой сдвиг её в него втыкает, а центр — якорь стяжки.
    ///
    /// Расчёт результата: экранный размах по горизонтали 58.3 -> 53.8 м, по
    /// вертикали 37.4 -> 31.0 м, дистанция вписывания 69 -> 63 м, площадь
    /// застройки в кадре +20%.
    ///
    /// Сдвиг применяется ОДНОЙ таблицей к раскладке, площадкам рельефа и
    /// кругам зон разом. Руками по трём массивам — это ровно тот случай,
    /// который уже стоил витка: на витке 17 объекты уехали, а воронка
    /// карьера осталась под пустым местом.
    /// </summary>
    private static readonly float[][] Styazhka =
    {
        // ВТОРОЙ ПРОХОД, по замеру собранного кадра. Первый проход дал
        // дистанцию 72 -> 67 м, и все четыре кромки кадра снова держат те же
        // четыре конца креста: лёд v +0.97, космопорт (текстильная фабрика)
        // v -0.95, жильё u -0.92, карьер u +0.90. Значит стягивать надо ещё
        // раз и всеми четырьмя сразу — один конец кадр не отпустит.
        //
        // Потолки, дальше которых идти нельзя, посчитаны, а не угаданы:
        //   жильё  +2.0 по x — правый столбец встаёт в 0.30 м от купола-героя
        //          при минимуме разводки 0.28 м; +2.5 уже втыкает;
        //   лёд    -3.0 по z — до северного ряда жилья остаётся 3.9 м, и в
        //          этом промежутке лежит новая цепочка груза (доктрина:
        //          промежуток между блоками не бывает пуст);
        //   карьер -2.5 по z — центр колодца уходит на (13.0, 25.0), до
        //          станции атмосферы 7.1 м; смягчение края воронки на этом
        //          расстоянии даёт перепад 0.3 м под её пятном, сторож
        //          косогора на прошлой сборке при 7.55 м молчал;
        //   космопорт +5.0 по z — северная кромка площадки шаттла встаёт на
        //          z = -1.25 при южной кромке купола-героя -3.15, по x они
        //          не пересекаются вовсе (7.4..16.6 против -5.5..5.5).
        // КРУГ 12, пункт 5 (тяжесть 2): «решётчатый зелёный купол оранжереи
        // и посадочная площадка шаттла стоят впритык друг к другу по
        // вертикали... на центральной вертикали кадра должен остаться один
        // пик внимания». Замер по кадру круга 11: купол проецируется в
        // px x 677, площадка в px x 757 — 80 px, то есть 5% ширины кадра при
        // собственной ширине каждого из двух пятен около 250 px.
        //
        // Купол сдвинуть НЕЛЬЗЯ, и это считается, а не предполагается: его
        // полугабарит 5.5 м, восточный столбец жилья стоит на x = -8 с
        // полугабаритом 2.2, то есть его кромка на -5.8 — купол уже стоит в
        // 0.3 м от неё и на запад не идёт ни на метр. Двигается площадка, и
        // ровно по ЭКРАННОЙ горизонтали (0.766, 0.643), чтобы не уехать вниз
        // кадра: (+2.5, +1.5) даёт du = +2.88 (это +82 px вправо) при dv
        // -0.32 (9 px вниз). Расчётный разнос 162 px вместо 80.
        // КРУГ 9 (зонирование), находки 1 и 3, тяжесть 1: «открытого
        // грунта-буфера между жильём и космопортом нет вовсе». Замер прошлой
        // сборки: 7.9 м при требовании доктрины «далеко = 10+ клеток = 25 м»,
        // и держал зазор не шаттл, а склад-ангар зоны 0 на x = 5.6 — то есть
        // в 1.4 м от купола-героя, внутри его же экранного пятна.
        // Космопорт уведён на +8 м по ЭКРАННОЙ горизонтали (0.766, 0.643):
        // du = +8.0, dv = 0.0 — по вертикали кадр не растёт вовсе, а по
        // горизонтали запас был 10.5 м (размах 50.9 при допустимых 61.4).
        new[] {  7.63f,  7.64f },  // 0 космопорт
        // Жильё на -2 м по той же оси, навстречу левой кромке: ещё два метра
        // разрыва до купола-героя, который прошлый круг держал на 0.3 м.
        // Сюда же переехали ОБЕ теплицы (kupol-tunnel) из космопорта и
        // промзоны — доктрина 3, карта соседства: «жилой квартал рядом:
        // вода, теплицы». Находка 6 разрешает именно этот вариант.
        // КРУГ 1 (ядро), стяжка периферии. Замер по МИРОВЫМ координатам
        // (таблица + стяжка зоны, ровно то, что строит сборщик): профиль
        // плотности от центроида застройки шёл 31.6 / 59.2 / 19.5 / 6.1 —
        // кольцо 10-20 м вдвое плотнее ядра. Прежний замер показывал
        // 81.1 / 47.7 / 15.6 / 5.7 и «задача закрыта», потому что читал
        // сырые числа таблицы, то есть считал все пять зон стоящими в одной
        // точке. Стяжка — единственная ручка, которая двигает зону ЦЕЛИКОМ:
        // и строки раскладки, и центр круга VZonu, и площадку рельефа под
        // ней. Перенос тех же объектов построчно оставил бы плато на месте.
        // Величина не угадана: покоординатный спуск с шагом 0.25 м при
        // условии «ни одной новой пары наложения и ни одна старая не стала
        // глубже». Жильё упёрлось на 0.75 м (потолок комментария выше — 2.0
        // по x, но там его держал купол-герой, которого больше нет).
        new[] {  1.18f,  0.94f },  // 1 жилой квартал
        // КРУГ 27 (зонирование), находки 1 и 5. Промзона была единственной
        // зоной с нулевой стяжкой — «упирается в купол, любой сдвиг в него
        // втыкает». Это верно для сдвига НА купол; сдвиг ОТ него не пробован
        // ни разу. Замер круга 26: kupol-tunnel промзоны стоял в 0.2 м от
        // купола-оранжереи, а западная кромка промзоны (zavod-pishchevoy,
        // мир x = −2.5) уходила западнее западной кромки карьера — то есть
        // промзона физически не могла работать буфером между карьером и
        // жильём, о котором просит находка 1: она стояла сбоку от обоих.
        //
        // Вектор (+2.0, −0.5) — это экранное «вправо» (0.766, 0.643) с малой
        // поправкой вниз: du = +1.21, dv = −1.67. Кадр от него не отъезжает
        // (расчётный экранный размах 54.0 -> 54.3 м), потому что кромки кадра
        // держат лёд сверху и площадка шаттла снизу, а не промзона.
        // КРУГ 9, находка 6, тяжесть 2: «купол-оранжерея стоит впритык
        // (зазор 20 px) к силосному складу промзоны». Замер: 0.0 м, пятна
        // zavod-pishchevoy и kupol-geodezicheskiy пересекались в плане.
        // Промзона на +7 по экранной горизонтали, расчётный зазор до купола
        // 8.6 м — вилка доктрины 8-12.
        new[] {  7.36f,  4.00f },  // 2 промзона
        // Лёд на -1 по экранной вертикали: он держал верхнюю кромку кадра
        // (v = 0.97), и метр вниз — это метр, который отдаётся карьеру.
        // КРУГ 1 (ядро): лёд стянут на 4.75 м к центроиду застройки. Он
        // держал ВЕРХНЮЮ кромку кадра (лог сборки: «держит кромку
        // burovaya-05, max(|u|,|v|)=0.97») при том, что до ближайшего
        // соседа-постройки от него 7 м пустого грунта. Запас был самый
        // большой в сцене: зазоры до зон 0, 2 и 4 стояли на 20.2, 16.9 и
        // 18.2 м при вилке доктрины 8-12. После стяжки экранная высота
        // застройки падает с 45.7 до 41.1 м, то есть VpisatKadr подводит
        // камеру и вся колония растёт на кадре.
        new[] {  8.63f, -6.35f },  // 3 ледяное поле
        // КРУГ 9, находки 2 и 5, тяжесть 1: «ледяное пятно без единого
        // разрыва переходит в буровую технику карьера». Замер: 5.6 м между
        // пятнами при требовании «далеко = 10+ клеток = 25 м».
        // Карьер уведён на +9 по экранной горизонтали и +2 по вертикали:
        // расчётный зазор до льда 24.6 м, до промзоны 7.3 м (находка 7).
        // Вертикаль карьеру бесплатна: его v = 15.3 против v = 24.0 у льда,
        // верхнюю кромку кадра держит лёд, а не он.
        // КРУГ 1 (ядро): карьер стянут на 3.0 м к центроиду. Он держал
        // ПРАВУЮ кромку кадра (burovaya-03, экранная координата u = 35.7 при
        // левой -23.2). Дальше 3.0 м идти нельзя и это посчитано: зазор до
        // промзоны стоял на 0.35 м и при большей стяжке уходит в минус, а
        // §3 разрешает касание, но не пересечение.
        new[] {  1.68f,  0.24f },  // 4 карьер
        new[] {  0.0f,  0.0f },   // 5 центр, якорь
        new[] {  0.0f,  0.0f },   // 6 пустошь: рамка кадра, не колония
        new[] {  0.0f,  0.0f },   // 7 расформирована
    };

    /// <summary>
    /// Какой зоне принадлежит каждая строка Pads. Индексы площадок рельефа
    /// НЕ совпадают с номерами зон (воронка и колодец карьера — две строки на
    /// одну зону), и без этой карты стяжка увезла бы застройку с площадки.
    /// </summary>
    // КРУГ 12: добавлен индекс 7 (останец burovaya-04, зона 4 карьера).
    // КРУГ 13: добавлен индекс 8 (грузовой двор причала, зона 0 космопорта) —
    // без строки здесь стяжка увезла бы новую площадку в мировой ноль, а двор
    // остался бы на природном склоне.
    private static readonly int[] PadZona = { 0, 1, 2, 4, 4, 3, 5, 4, 0 };

    static ColonyOursBuilder()
    {
        for (int i = 0; i < Pads.Length; i++)
        {
            Pads[i][0] = Pads[i][0] * Spread + Styazhka[PadZona[i]][0];
            Pads[i][1] = Pads[i][1] * Spread + Styazhka[PadZona[i]][1];
            Pads[i][2] *= Spread;
        }
        for (int z = 0; z < Zones.Length; z++)
        {
            Zones[z][0] = Zones[z][0] * Spread + Styazhka[z][0];
            Zones[z][1] = Zones[z][1] * Spread + Styazhka[z][1];
            Zones[z][2] *= Spread;
        }
        foreach (var row in Layout)
        {
            int z = (int)row[7];
            row[1] = (float)row[1] * Spread + Styazhka[z][0];
            row[2] = (float)row[2] * Spread + Styazhka[z][1];
        }

        PadsBig = (float[][])Pads.Clone();
        System.Array.Sort(PadsBig, (a, b) => b[2].CompareTo(a[2]));
    }
    // Понижено со 241 до 161 (правка отката, свод, виток 19, раздел
    // «Децимация»). Вердикт тяжести 1 обоих оценщиков: 2 410 790 треугольников
    // при потолке 250 000. Земля 240*240*2 = 115 200 треугольников давала
    // почти половину всего базового потолка на одной гладкой поверхности.
    // 160*160*2 = 51 200, минус 64 000; шаг сетки растёт с 0.413 до 0.620 м,
    // Height() не меняется, поэтому размах рельефа 2.3 м сохраняется —
    // меняется частота выборки, а не форма.
    private const int Grid = 161;         // вершин на сторону

    // ОХВАТ СЕТКИ ЗЕМЛИ. Было World*1.6 = 99.2 м, то есть ±49.6 м по каждой
    // оси, и это число прямо давало находку 1 круга 15 (тяжесть 1): «в правом
    // верхнем углу кадра плоское блёкло-лавандовое пятно, отрезанное от
    // оранжевого склона резкой диагональю; через дыру виден край меша».
    //
    // ЗАМЕР, а не догадка. Диагональ пятна прослежена по PNG попиксельно:
    // небо (237,198,173) занимает 1.17% кадра, граница идёт из px(1334,0) в
    // px(1600,~130). Кромка меша z = +49.6 при камере кадра (цель (10.7,-2.4),
    // азимут -50, наклон 44, поле 32, дистанция 68) проецируется через
    // px(1382,34) и px(1548,109) — совпадение с замеренной границей в
    // пределах шума рельефа. То есть это НЕ горизонт, а торец сетки.
    // Обратная проекция того же угла: px(1350,0) требует грунта на (5.7,54.7),
    // px(1590,90) — на (22.7,45.5). Сетка кончалась на 49.6.
    //
    // 2.2 берётся счётом: самый дальний ВИДИМЫЙ грунт после правки рельефа
    // (дальняя гряда в Height ниже) лежит на r = 55.5 м; ±68.2 даёт запас
    // 12.7 м, то есть пять клеток за кромкой кадра при требовании находки
    // «минимум 1-2 клетки». Треугольников земля от этого не прибавляет ни
    // одного: Grid не тронут, меняются координаты вершин, а не их число. Шаг
    // сетки растёт с 0.620 до 0.853 м — средняя октава рельефа (длина волны
    // 20 м) берётся 23 выборками вместо 32, форма 2.3-метрового размаха
    // сохраняется.
    private const float ZemlyaOhvat = World * 2.2f;
    private const float TexPeriod = 11f;
    // Клетка 2.5 м. Доктрина, раздел 0: решение принято, а не отложено.
    // При клетке 4 м постройка 5-6 м занимала 1.25-1.5 клетки, то есть
    // дробное число, и целочисленная сетка была невозможна в принципе.
    private const float Cell = 2.5f;

    // площадки: x, z, радиус, высота плато
    // Ось роста колонии от точки посадки вглубь месторождений:
    // космопорт -> жилой квартал -> промзона -> карьер (аудит геймдизайна).
    // Рельеф следует за логикой поселения, а не наоборот:
    // жилой квартал на пологом возвышении (видовая точка, сухо),
