    /// массиве, он был скрытой зависимостью: уступ карьера, дописанный в
    /// конец списка, стер бы дно, потому что применился бы последним.
    /// </summary>
    private static float[][] PadsBig;

    // Зоны колонии для разводки. Расталкивая постройки, нельзя вынести
    // жилой дом в карьер: объект остается в круге своей зоны.
    // x, z, радиус
    private static readonly float[][] Zones =
    {
        // Пять кластеров по числу функциональных зон плюс центр под героя.
