        // соседствует с жильём, которому нужна вода (карта соседства 3).
        // Центр сдвинут вместе с Pads[0] на (19.0,-11.5), радиус не менялся
        // (igrok т.2, см. комментарий у Pads[0]).
        // КРУГ 2: центры зон пересчитаны под уплотнение (см. комментарий у
        // Pads выше). Замер экранных осей до правки: ширина 60.7 м, высота
        // 46.7 м — кадр держала высота, дистанция вписывания 87 м. Лёд и
        // космопорт стянуты навстречу по экранной вертикали, жильё расширено
        // на четвёртый столбец вместо отдельной парцеллы.
        // Радиус 10 -> 13 (круг 10): в зону 0 встаёт второй склад причала на
        // (4.0, −11.0) мировых, его удаление от центра зоны 11.0 м плюс
        // полугабарит 3.2 — при радиусе 10 зажим VZonu утащил бы постройку
        // обратно к шаттлу и дыра в нижней трети кадра осталась бы.
        new[] { 13.5f, -9.0f, 13.0f },    // 0 космопорт, ближний план, вход
        new[] { -17.5f, -3.0f, 13.0f },   // 1 жилой квартал
        new[] { 9.0f, 14.0f, 9.0f },      // 2 промзона
        // Лёд и карьер отодвинуты на виток 2026-08-17 по вердикту оценщика
        // кадра: «жильё и лёд слиплись в один нечитаемый ком, разрыва в 8-12 м
        // между ними нет вообще». Замер подтвердил: от края жилья до края
        // льда было 3.2 м при требовании доктрины 1.5 в 8-12 м. Карьер так же
        // сросся с промзоной. Кластер, у которого нет границы, на сжатии до
        // ширины магазинной карточки перестаёт быть кластером.
        // КРУГ 9, находки 2 и 5: радиус 11.0 -> 9.0. Зажим VZonu держит
        // объект внутри круга зоны, и при 11.0 буровая-02 могла законно
        // стоять в 8.7 м от центра пятна, то есть тянуться к карьеру.
        // Фактическая потребность зоны ниже девяти, поэтому 9.0 ничего не
        // ломает, а восточный форпост льда подтягивает к своим.
        new[] { -17.5f, 18.0f, 9.0f },    // 3 ледяное поле, дальний угол
        // Радиус поднят с 8.0 до 11.0 (sistema, тяжесть 1 и 2): в зону 4
        // переезжает stantsiya-atmosfernaya (полугабарит 3 м), зажим VZonu
        // держит 11-3=8 м, фактическое удаление станции от центра зоны
        // 7.43 м — станция остаётся там, куда поставлена, зажим её не тронет.
        // КРУГ 27, третий проход. Радиус поднимали с 8.0 до 11.0 РАДИ
        // stantsiya-atmosfernaya, которая переехала в зону 4; кругом позже она
        // вернулась в промзону, а радиус остался. Замер собранного кадра: за
        // 240 проходов разводка не сошлась (88 наложений), и весь избыток она
        // вентилирует на ЗАПАД — единственную свободную сторону карьера, то
        // есть в полосу, которую находка 1 требует держать пустой. VZonu
        // отрабатывает после КАЖДОГО прохода и потому сильнее разводки; 9.5 —
        // это ровно фактическая потребность зоны (sqrt(площадь пятен/pi)*1.5 =
        // 9.7 м), ниже неё зажим просто перестаёт действовать.
        new[] { 10.3f, 26.0f, 9.5f },     // 4 карьер, за промзоной
        // КРУГ 6, находки 1 и 3: центр зоны сдвинут вместе с куполом-героем
        // на -4.0 по x, иначе зажим VZonu вернул бы его на старую ось.
        // КРУГ 28: +2.5 по z вместе с куполом — тот же довод, другая ось.
        new[] { -4.0f, 4.5f, 6.0f },      // 5 центр: купол-оранжерея, герой
        new[] { 0.0f, 0.0f, 34.0f },      // 6 пустошь
        // 7 ПУСТАЯ. Парцелла роста расформирована (круг 2, тяжесть 2 про
        // одиночный купол). Строку держим, чтобы не сдвигать индексы зон в
        // раскладке; членов у зоны нет, и все циклы по зонам её молча
        // пропускают (chleny.Count == 0).
        new[] { -17.5f, -3.0f, 1.0f },    // 7 расформирована
    };

    // Бюджет треугольников ПО КАТЕГОРИЯМ. Сцена весила 2.8 млн - для
    // Play Market превышение на порядок (казуальное 3D на телефоне живет
    // в 150-300 тысячах). Герой кадра может позволить больше, камень нет.
    private static int BudgetFor(string name)
    {
        if (name == "shuttle" || name == "ploshchadka-shattla") return 16000;
        if (name.StartsWith("zavod") || name.StartsWith("fabrika")
            || name.StartsWith("sklad") || name.StartsWith("stantsiya")
            || name.StartsWith("kupol") || name.StartsWith("zhiloy")) return 9000;
        if (name.StartsWith("burovaya") || name.StartsWith("dron")) return 6000;
        if (name.StartsWith("grunt")) return 5000;
        return 1800;   // декор, камни, грузы
    }

    private const int PitPad = 3;           // индекс чаши для темного субмеша

    // имя, x, z, размер по длинной горизонтали, поворот, доля утопления
    // Метровый эталон по аудиту геймдизайна (loop/ours/gamedesign-audit.md,
    // раздел 1). Иерархия: завод > склад ~ шаттл > буровая > купол > дрон.
    // Отрицательный размер = задана ВЫСОТА, положительный = длина.
    // Столбцы: имя, x, z, размер, поворот, утопление, подъем, зона, связка.
    // «Связка» - объекты, которые ОБЯЗАНЫ стоять вместе и потому не
    // расталкиваются друг от друга: шаттл на своей площадке, буровая на
    // льду, экскаватор в чаше карьера. Это и есть логика места: техника
    // стоит там, где работает, а не там, где нашлось пустое место.
    private static readonly object[][] Layout =
    {
        // Раскладка по доктрине, редакция 2.
        //
        // Внутри кластера постройки стоят с зазором 0-1 клетка (0-2.5 м), между
        // кластерами 8-12 м открытого грунта. Повороты ТОЛЬКО кратно 90.
        //
        // В связке первый член — ОСНОВАНИЕ, остальные садятся НА него по
        // высоте. Это лечит «шаттл застрял в здании» и «техника застряла во
        // льду»: перекрытие в плане у них норма, дефектом было перекрытие
        // высот.

        // ===== КЛАСТЕР 0: КОСМОПОРТ И ОТГРУЗКА, ближний план, точка входа =====
        //
        // КРУГ 2. Зона целиком подтянута с (18.1, -10.4) на (13.5, -9.0) —
        // это ближний конец самой длинной, экранно-вертикальной оси колонии
        // (второй конец — ледяное поле). Замер до правки: экранная высота
        // колонии 46.7 м держала дистанцию вписывания на 87 м, при том что по
        // ширине хватало 70 м, и крайние колонки кадра по 200 px стояли с
        // детальностью 0.0%. Сокращение этой оси — единственный численный
        // рычаг под вердикт тяжести 1 «застройка 8.0% при цели 17-25%»:
        // ближе камера — крупнее вся застройка на кадре.
        // КРУГ 3, пункт 5 (тяжесть 2): «буровая, купол и ракета расставлены на
        // диагонали с равным шагом и равным зрительным весом — три полюса
        // вместо одного героя». Из трёх ракета самая уникальная по силуэту
        // (единственная вертикаль-стрела на плоской колонии), ей и быть
        // героем. Площадка и шаттл подняты на 25% (7.6->9.5, 6.2->7.75):
        // площадь пятна растёт на 56%, что и даёт нужные «в полтора-два раза
        // крупнее соседей» без переезда зоны — VpisatKadr сам пересчитает
        // кадр под новый фактический габарит.
        // Причал отодвинут по z с -11.0 на -12.2 (круг 8, часть пункта 2 про
        // единственного хозяина центра). Замер собранного кадра: после
        // уплотнения разводка вывела площадку на (10.8, -5.7) при куполе-герое
        // на (0.1, 1.7) — зазор в плане 0.6 м, и на кадре нос шаттла лёг
        // ПОВЕРХ нижней дуги купола, то есть два главных силуэта слиплись в
        // один. 1.2 м по z дают зазор 1.8 м и разводят их на кадре.
        //
        // Кадр от этого НЕ отъезжает: нижнюю кромку держит не причал, а
        // текстильная фабрика (экранная «высота» -14.8 против -13.6 у
        // площадки), и после сдвига площадка встаёт на -14.2 — всё ещё выше
        // фабрики. Дистанция вписывания не меняется.
        //
        // КРУГ 6, находки 1 и 5 (тяжесть 1 и 2): «купол-оранжерея спорит за
        // центр с площадкой шаттла, разница площадей силуэтов меньше 10%»,
        // «жилой кластер (~8% кадра) весит больше точки входа (~3% кадра)».
        // Купол-герой сдвинут с центральной оси (см. Layout зоны 5), здесь —
        // вторая часть того же лечения: площадка и шаттл подняты на 32%
        // (9.5->12.5, 7.75->10.2), площадь пятна растёт в 1.73 раза.
        //
        // Первая попытка подняла размер на 47% (9.5->14.0) и провалилась
        // ПОБОЧНЫМ эффектом: BuildFigury ставит фигуру-приветчика у площадки
        // выносом = полугабарит площадки + 0.8 м, и полугабарит 7.0 м вынес
        // фигуру на 11.73 м к камере — фигура сама стала «ближе всего к
        // камере», усилив находку 2 вместо того чтобы её не трогать. Лечится
        // не размером площадки, а потолком выноса в BuildFigury (см. правку
        // там же, круг 6) — вынос теперь не выше 8.5 м ни у какого якоря,
        // поэтому площадку можно растить, не отращивая фигуре ноги.
        // КРУГ 13, ПОБОЧНЫЙ ЭФФЕКТ ПЕРВОГО ПРОХОДА, замерен и вылечен здесь.
        // Грузовой двор ниже закреплён (четыре объекта, которые разводка не
        // двигает), и вся его нагрузка ушла на единственную крупную подвижную
        // фигуру зоны — на сам причал. Замер сборки: причал уехал с
        // (13.9,-2.1) на (26.3,-0.5), то есть на 12.4 м на восток, и шаттл
        // на кадре встал в px 1155 вместо 807 — точка входа игрока уползла к
        // правой кромке. Ровно тот класс ошибки, о котором предупреждает
        // правило «двигаешь объект — двигай зависимости»: связка port
        // компенсировала чужое давление, потому что была единственной, кому
        // разрешено двигаться.
        //
        // Причал закреплён на своей ПРОВЕРЕННОЙ точке (13.75,-2.5) — та же,
        // куда его вывела разводка прошлых кругов, с округлением на узел
        // полуклетки. Все композиционные расчёты предыдущих кругов (герой
        // против точки входа, вынос фигуры-приветчика, наводка кадра) считаны
        // от неё, и сохранить её дешевле, чем пересчитывать заново.
        // Зазоры от закреплённого причала до нового двора: до склада 0.65 м
        // по z, до ящика причала 1.15, до второго резервуара 1.74 по x.
        //
        // КРУГ 18 (силуэт и масштаб), находка 1 (тяжесть 1), дословно: «нос
        // шаттла уходит за кромку площадки и зависает над открытым грунтом
        // рядом с теплицей». Доктрина расстановки числит это ОТКРЫТЫМ
        // дефектом с круга 3 («Шаттл стоит не на площадке: 83% в плане, 71%
        // по высоте»), а не исправленным — прошлые круги лечили только
        // ВЕРТИКАЛЬНУЮ посадку (PosaditNaOsnovanie, шаттл больше не тонет и
        // не парит по Y), но не горизонтальный охват: шаттл и площадка стоят
        // в одной точке, но площадка — круг, а шаттл — вытянутый эллипс
        // 10.2x7.5, и его нос по длинной оси выходит за окружность круглой
        // площадки, даже когда центры совпадают день в день.
        //
        // Лечение находки — рост площадки, а не сжатие шаттла: находка 2
        // этого же круга требует шаттл ВЫШЕ соседей, а Place масштабирует
        // все три оси одним k (см. комментарий у burovaya-04 ниже), поэтому
        // урезание шаттла срезало бы и высоту, которую находка 2 просит
        // расти. Размер +20% (12.5 -> 15.0, нижняя граница вилки находки
        // 20-25%, выбрана экономно): полурадиус растёт с 6.25 до 7.5 м, чего
        // достаточно, чтобы накрыть длинную ось шаттла (полудлина 5.1 м)
        // с запасом даже при не по центру взятом продольном габарите модели.
        // Потолок выноса фигуры-приветчика (круг 6, BuildFigury) — 8.5 м;
        // здесь полурадиус + 0.8 = 8.3, ниже потолка, побочный эффект круга 6
        // не возвращается.
        // Площадка Zakreplen (последняя колонка true), Razvesti её саму не
        // двигает; выросшая площадка приблизится к грузовому пятачку причала
        // (dekor-07 "gruz" ниже, ближайшая точка в 6.9 м от центра площадки
        // при новом полурадиусе 7.5) — разводка раздвинет их сама, это её
        // работа, а не ручная перестановка.
        // КОСМОДРОМ ВЫНЕСЕН ИЗ ЦЕНТРА, спека шаг 6.
        //
        // Стоял в (6.12, -10.14) — самый крупный силуэт кадра ровно посередине,
        // и забирал роль героя у главного купола. По разбору жанра транспортный
        // узел — это ворота во внешний мир, его место у границы, а не в ядре.
        //
        // Направление считано с камеры, а не на глаз: азимут -50 градусов даёт
        // экранное «вправо» в мире (0.766, 0.643), значит «влево-вниз» это
        // примерно (-0.28, -0.96). Отсюда сдвиг на 18 метров.
        // Площадка уменьшена с 15.0 до 11.0. Уйдя из центра, она встала БЛИЖЕ
        // к камере и от этого стала крупнее в кадре, чем была: заняла четверть
        // экрана и снова забрала роль героя, только теперь с переднего плана.
        // Перспектива работает против выноса, и лечится это размером, а не
        // ещё одним переносом.
        // КРУГ 2 (герой), находка «оптический центр кадра занят космопортом».
        // Замер тремя оценщиками сошёлся: связка площадка+закрытый шаттл
        // держит 18.4% силуэтной массы кадра (336.5 м2) против 3.6% (66.3 м2)
        // у башни-героя, разрыв в 5.1 раза, и в центральном прямоугольнике
        // кадра (30x30% экрана) космопорт занимает 91.4%, жильё и купола 0.7%,
        // герой 0%. Уменьшение с 15.0 до 11.0 прошлым кругом порт не сняло:
        // уйдя на передний план, он забрал перспективу.
        //
        // Коэффициент 0.773 (11.0 -> 8.5) применён ВСЕМ ТРЁМ строкам порта
        // одинаково, поэтому свес корабля за бетон не меняется: полурадиус
        // площадки 5.35 -> 4.13, полудиагональ корпуса 5.52 -> 4.27, свес
        // 0.17 -> 0.14 м. Диск остаётся 260 px поперёк — порт читается портом.
        // СКЛАД МОДЕЛЕЙ. Всё, что есть в библиотеке и не стоит в колонии,
        // выложено рядами у северного края карты. Раскладку владелец
        // делает сам — здесь только доступ ко всему, что создано, чтобы
        // ничего не лежало в папках неиспользованным.
        new object[] { "figura-neset", -27.0f, 44.0f, 1.8f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "figura-osmatrivaetsya", -21.0f, 44.0f, 1.8f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "figura-ukazyvaet", -15.0f, 44.0f, 1.8f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "figura-ukazyvaet-variant", -9.0f, 44.0f, 1.8f, 0f, 0f, 0f, 0, "sklad-modeley" },
        // ДРОНЫ В КОЛОНИИ, по одному на зону — у той работы, к которой
        // приписаны: курьерский над космодромом, средний у производства,
        // тяжёлый над добычей. Подъём 2.6-3.4 м даёт зависание: дрон,
        // стоящий на грунте, читается брошенным, а не работающим.
        new object[] { "dron-t1", 5.6f, -14.2f, 2.6f, 0f, 0f, 2.6f, 0, "port" },
        new object[] { "dron-t2", 11.8f, 6.4f, 2.8f, 90f, 0f, 3.1f, 0, "promzona" },
        new object[] { "dron-t3", 12.2f, 22.0f, 3.0f, 0f, 0f, 3.4f, 0, "karyer" },
        new object[] { "ballony-na-poddone", 15.0f, 44.0f, 2.4f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "led-kristally", 21.0f, 44.0f, 3.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "led-kristally-variant", 27.0f, 44.0f, 3.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "led-glyba-kolotaya", -27.0f, 53.0f, 3.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "led-glyba-kristallicheskaya", -21.0f, 53.0f, 3.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "led-greben", -15.0f, 53.0f, 3.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "led-skvazhina", -9.0f, 53.0f, 3.2f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "led-valun-v-shube", -3.0f, 53.0f, 3.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "kupol-grib", 3.0f, 53.0f, 5.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
        new object[] { "sklad-modeley-kupol-tunnel", 9.0f, 53.0f, 6.0f, 0f, 0f, 0f, 0, "sklad-modeley" },
