        // снято кругом 4: dekor-09 (14.00, 45.50) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (18.50, 46.00) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-01 (22.50, 45.00) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (25.50, 38.50) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.

        // ДОБОР ПО ПОВТОРНОМУ ЗАМЕРУ. Тот же счёт по пересобранному кадру
        // (raskladka-fakt.md после первой сборки круга) оставил на кромке два
        // разрыва того же класса, что и названные находками, но не названные:
        //   лево  px 0-40, py 590-770  — 180 px, между камнем (-4.0,-22.0) и
        //         угловой тройкой круга 7 (2.4,-29.0);
        //   верх  px 220-360           — 140 px, между (-29.8,-2.5) и (-25,8.8).
        // Критерий доктрины (раздел 7 п.8) — непрерывность ВСЕЙ полосы, а не
        // тех её кусков, на которые указали пальцем; закрываю обе, раз счёт
        // уже стоит. Запас до чужого габарита 2.03 / 4.30 / 2.83 / 0.70 м.

        // ===== КРУГ 23: ТРИ ПРОРЕХИ КАЙМЫ ПО КРОМКЕ ОБЩЕГО ПЛАНА =====
        //
        // Находки 1, 2 и 3 (все тяжесть 2) описывают один дефект с трёх
        // сторон: «кайма плотная по углам, но разрывается верх-центром и
        // низ-центром, голый охристый склон идёт прямо до обреза кадра».
        // Свод §10: «открытого голого склона за буфером в кадре быть не
        // должно». Доктрина §7.8: критерий — непрерывность ВСЕЙ полосы.
        //
        // ЗАМЕР, а не глазомер. Взят вывод ZamerKromki круга 22 (139 камней
        // пустоши, пиксели по фактическим габаритам собранной сцены) и по
        // нему построен список камней, чей НИЗ приходится на краевые полосы
        // кадра. Сортировка по px даёт три дыры и ровно три:
        //   верх  px 509 -> 785   276 px  (находка 1 назвала 650-980, «330»)
        //   верх  px 1096 -> 1442 346 px  (не названа ни одной находкой)
        //   низ   px 138 -> 724   586 px  (находки 2 и 3, «450 px»)
        // Нижняя дыра — больше трети ширины кадра, и она же самая грубая:
        // ближние камни ЕСТЬ ((8.8,-25.8), (11.6,-23.6), (14.4,-21.4)), но
        // стоят основаниями на py 878-885, то есть полоса py 885-1000 под
        // ними пуста на всю ширину. Это не «нет камней», это «камни не
        // доведены до кромки»: лечится не количеством, а радиусом.
        //
        // Обратная проекция считана по камере СНЯТОГО кадра круга 22 —
        // цель (11.4, 0.6, -2.5), азимут -50, подъём 44, дистанция 65, поле
        // 32. Проверка проекции на восьми уже стоящих камнях: расхождение
        // 0-3 px по столбцу и 0-18 px по строке (строка гуляет на высоту
        // рельефа, столбец не гуляет вовсе). То есть числа ниже — замер, а
        // не оценка.
        //
        // Все строки помечены десятой колонкой (Zakreplen): радиус зоны 6 —
        // 34 м, VZonu утащила бы половину точек обратно на плато молча, та
        // же ловушка, что у внешней дуги круга 7 и у кучки круга 22.

        // НИЖНЯЯ КРОМКА, находки 2 и 3. Внешняя дуга r 28.8-31.0 от центра
        // карты по юго-восточному лучу: девять камней тремя кучками (доктрина
        // 5, пункты 2-3 — «кучка 2-5, один крупный плюс пара мелких»), шаг по
        // экрану 58-65 px, основания py 972-980. Полоса py 885-1000 в столбцах
        // px 169-677 закрывается целиком.
        //
        // Почему дуга безопасна по рельефу: все девять точек лежат внутри
        // площадки грузового двора Pads[8] (11.3,-23.5, радиус 12.5, высота 0,
        // ядро 0.70 = 8.75 м) либо на её краю — удаления 3.5-11.1 м. Земля там
        // выровнена в ноль самой площадкой, поэтому проекция при y=0 точна, а
        // сторож косогора на этих строках промолчит: перепада нет.
        //
        // Зазоры до чужого габарита (считаны по фактической раскладке круга
        // 22, правило TrebuemyyZazor для закреплённой скалы зоны 6): до
        // (7.0,-28.6) 2.82 при 1.65; до (8.8,-25.8) 3.53 при 1.65; до
        // (11.6,-23.6) 3.26; до (14.4,-21.4) 3.05; до sklad-bunkery
        // (18.8,-17.5) 4.50 при 4.00; до (23.4,-20.2) 2.12 при 2.00.

        // ДОБОР ТОЙ ЖЕ ДУГИ: УГОЛ НИЗ-ЛЕВО. Дуга выше закрыла полосу
        // px 169-677, но замер СНЯТОГО кадра (проба гладкости по столбцам:
        // от нижней кромки вверх до первого перепада яркости > 14) показал
        // остаток — столбцы px 2-110 гладкие на 123-161 px вверх от обреза.
        // Причина видна в самой дуге: её западный конец (4.5,-27.5) и
        // (2.4,-29.0) сидит на py 782-834, то есть на 150 px выше кромки, а
        // юго-западнее него в пустоши не стоит ничего.
        //
        // Три камня по обратной проекции общего плана, основания на py 893,
        // 940 и 1019 (последний за обрезом — в кадр входит только макушка с
        // py 975, чего и надо от кромочного камня):
        //   (3.9,-30.6) px 23  py 844-893
        //   (6.2,-30.8) px 60  py 883-940
        //   (9.3,-31.6) px 97  py 975-1019
        // Экранная ширина камня здесь 16 px на метр, то есть 50-55 px на
        // штуку: тройка перекрывает столбцы px 0-125 без просвета.
        //
        // Зазоры (правило TrebuemyyZazor для закреплённой скалы зоны 6,
        // требуется 1.65-2.00): между собой 2.31 и 3.20; до (2.4,-29.0) 2.19;
        // до (4.5,-27.5) 3.16; до (7.0,-28.6) 2.34; до (9.7,-29.4) 2.24; до
        // (11.3,-28.3) 3.86.
        //
        // Рельеф: все три внутри площадки грузового двора Pads[8]
        // (11.3,-23.5, радиус 12.5, ядро 8.75) — удаления 10.25, 8.90 и 8.34 м.
        // Дальний из них стоит на 18% склейки, где средняя октава гуляет на
        // десятые доли: сторож косогора на этих строках промолчит.

        // ВЕРХНЯЯ КРОМКА У ЛЕДЯНОГО ПОЛЯ, находки 1 и 3. Находка описывает
        // место верно («там, где дорога уходит вверх к ледяному полю»), но
        // трактует его как выезд за кадр: дороги там нет, магистраль на этом
        // конце КОНЧАЕТСЯ у ледяного поля. Прорези под проезд поэтому не
        // требуется — за полем ничего не едет. Оставлять её значило бы
        // оставить ту самую дыру, ради которой круг.
        //
        // Два ранга вместо одного. Один ранг на z 24-28 дал бы основания на
        // py 18-33 при высоте камня 50 px — то есть камни ушли бы макушками
        // за верхний обрез, а полоса py 35-60 осталась голой (ближние камни
        // (-8.5,20.0) и (-4.5,22.5) начинаются только с py 60). Второй ранг
        // на z 22.4-24.0 садится основаниями на py 41-51 и сшивает дальний
        // ранг с уже стоящими — кромка становится сплошной от py -20 до 103.
        //
        // Буфер до застройки держится по своду §10 (0.5-1 ширина здания =
        // 2.2-4.4 м при жилом куполе 4.4 м): ближайшая точка дальнего ранга
        // отстоит от grunt-led-2 (-19.1,20.4) на 4.00 м, ближнего — на 3.69 м.
        // Обе внутри вилки, и обе больше требуемого разводкой (2.92-3.32 м),
        // так что лёд с места не сдвинется.
        // снято кругом 4: dekor-09 (-18.80, 24.40) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-01 (-16.60, 24.80) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.

        // ВЕРХНЯЯ КРОМКА СПРАВА, px 1096-1442. Находками не названа, но это
        // та же полоса и тот же класс: доктрина §7.8 требует непрерывности
        // ВСЕЙ каймы, а не только тех кусков, на которые указали пальцем —
        // ровно тем же доводом круг 22 закрывал свой добор.
        //
        // Точки лежат на ближнем склоне дальней гряды (r 36-44). Ту же
        // зависимость держала кучка круга 22 на (14..25, 38..46): без гряды
        // земля там ниже плато и камень висит, с грядой она на +0.3…+1.1 м.
        // Радиус взят МЕНЬШЕ, чем у кучки круга 22 (36-44 против 41-48),
        // поэтому запас по высоте только больше, а размеры оставлены 2.4-3.4
        // против 3.8-4.8 — на удалении 75-90 м это 60-85 px ширины, вдвое
        // меньше жилого купола: находка круга 9 про силуэтный вес не задета.
        // снято кругом 4: dekor-09 (3.00, 36.20) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        new object[] { "dekor-01", 4.6f, 37.2f, 2.4f, 140f, 0.25f, 0f, 6, "", true },
        // снято кругом 4: dekor-09 (5.90, 38.20) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (9.20, 40.60) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-01 (10.60, 41.60) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (11.90, 42.60) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.

        // ВЕРХ-ЛЕВО КРУПНОГО ПЛАНА КАРЬЕРА, вторая половина находки 1: «тот же
        // провал виден с другой камеры: на karier.png это верхний левый угол —
        // гладкая дюна без единого камня, уходящая за границу изображения».
        //
        // Почему эти камни не видны на ОБЩЕМ плане и потому не считаются
        // добором его каймы. Обратная проекция общего плана кладёт все двенадцать
        // на px 1642-2258 при ширине кадра 1600 — то есть целиком за правым
        // обрезом. Это кайма ТОЛЬКО крупного плана, и она не может ни утяжелить
        // силуэт общего, ни отодвинуть его вписывание (VpisatKadr считает зоны
        // 0-5 и 7, пустошь в расчёт не входит).
        //
        // Числа сняты обратной проекцией камеры карьера (цель 15.4/25.6,
        // азимут 135, подъём 26, дистанция 21.6, поле 40). Верх-левая четверть
        // кадра разворачивается в дальнюю пустошь r 40-58 от центра карты —
        // это горизонт ЗА кромкой плато, поэтому кучки идут дугой по радиусу,
        // а не рядом. Четыре кучки по три (доктрина 5, пункты 2-3: один
        // крупный плюс пара мелких), их след на кадре карьера:
        //   K1 (47-50, 21-24) -> px 111-200, py 2-130
        //   K2 (37-41, 17-19) -> px 388-464, py 22-150
        //   K3 (32-36, 25-29) -> px 119-258, py 85-241
        //   K4 (50-54, 14-17) -> px 255-330, py -10-89
        // Вместе они закрывают полосу px 110-465 на всю высоту верхней
        // четверти. Угол px 0-110 остаётся песком намеренно: там r > 58, это
        // уже кромка самого меша земли (ZemlyaOhvat/2 = 68.2 м), и камень там
        // встал бы на обрыв полотна.
        //
        // Размеры 2.4-3.8 м — те же, что у остальной каймы. На удалении 30-45 м
        // от камеры карьера это 90-140 px по высоте: кучка читается силуэтом,
        // не превращаясь во второго героя.
        // снято кругом 4: dekor-01 (46.30, 21.50) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (49.80, 21.00) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (39.10, 19.00) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-01 (37.60, 17.40) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (41.20, 17.80) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (34.60, 28.50) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-01 (32.40, 26.20) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (35.60, 25.40) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (52.00, 17.00) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-01 (50.20, 15.00) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.
        // снято кругом 4: dekor-09 (53.80, 14.40) — ВНЕ КАДРА по логу [кромка], камень забракован владельцем.

        // ===== ГРАНИЦА ОСВОЕННОЙ ТЕРРИТОРИИ: СИГНАЛЬНЫЕ СТОЛБИКИ =====
        //
        // КРУГ 11, пункт 10 (тяжесть 2): «между тремя зонами колонии лежат
        // обширные ровные промежутки голого грунта без каймы, технопокрытия
        // или маркеров освоенной территории». Полосы технопокрытия физически
        // УЖЕ есть — BuildPerekhodnyySloy кладёт пять пятен «расчищено, но не
        // отстроено» (frontir/frontir-yug/frontir-prichal/frontir-vostok/
        // frontir-karier), это ровно доктрина 8.8. Чего не было — предметного
        // маркера НА них: пятно цвета без столбика читается тональным пятном
        // грунта, а не границей стройки.
        //
        // dekor-05 (флагшток на квадратном постаменте, уже стоит в клине у
        // причала) — готовый словарь «сигнальный столбик», новых моделей не
        // требуется. Точки — ЦЕНТРЫ уже посчитанных пятен: это заведомо
        // открытый грунт (round 2/4 подбирали их именно по низкой плотности
        // объектов в кадре), лишняя проверка регламентом 5.4 тут не нужна.
        // КРУГ 21: столбик (11.0,-14.0) -> (4.0,-17.5). Стоял внутри пятна
        // восточного бункера второго ряда двора. Зазор до бункера
        // (8.75,-13.75) по x 4.75 при требуемых 4.20, до склада-ангара
        // (10.0,-20.0) по x 5.25 при требуемых 4.85.

        // ===== РЕКВИЗИТ У ЦОКОЛЕЙ: РОВЕРЫ ВЕРНУЛИСЬ К ПОСТРОЙКАМ =====
        //
        // КРУГ 4, пункты 9 и 15 (тяжесть 2): «у оснований построек почти нет
        // реквизита», «одиночные тёмные предметы разбросаны поштучно, без
        // группировки у зданий»; свод, раздел 8: «ни одна фигура не стоит
        // посреди пустого грунта: у входа, на стыке дорог, у техники, у груза».
        //
        // Это ПЕРЕЕЗД, а не добавление: те же девять dekor-08, что стояли в
        // кайме и на южном подходе. Ни одного нового треугольника.
        //
        // Каждый ровер идёт со своим именем связки. Механизм тот же, что у
        // ящиков жилого ряда (dom-r1-*): связка из одного члена не сажается на
        // основание (PosaditNaOsnovanie требует Count >= 2), не разводится от
        // постройки на клетку (TrebuemyyZazor возвращает 0.15 м для
        // поставленного предмета) и не судится регламентом 5.4. Ровер обязан
        // стоять У цоколя, а не в 2.5 м от него.
        //
        // Точки посчитаны перебором по восьми направлениям от каждой постройки
        // с шагом отступа 0.5 м; взята первая, где зазор до всего остального не
        // меньше 0.30 м. Приоритет направления — юг и юго-восток, то есть
        // сторона, обращённая к камере.
        // КРУГ 6, пункт 6 (тяжесть 2): «одинаковые серые ящики-контейнеры
        // стоят поодиночке на голом грунте вне зданий: под ледяным пятном
        // вверху, у спутниковой тарелки справа, у площадки шаттла внизу».
        // Доктрина, «Груз — не декор»: одиночный предмет посреди грунта без
        // связи с постройкой подлежит удалению, а не отодвиганию; раздел 5.2:
        // кучками по 2-5, а не поштучно.
        //
        // Замер по трём названным: teh-dom1 стоял в 2.1 м от цоколя купола,
        // teh-led — в 4.6 м от линзы льда (ближайший объект вообще), teh-sklad
        // — в 6.5 м от купола-тоннеля и в 1.9 м от тарелки dekor-03, то есть
        // рядом с ДЕКОРОМ, а не с постройкой. Все три переставлены к цоколю:
        // teh-dom1/2 встают в один штабель с ящиками жилого ряда (кучка из
        // двух силуэтов вместо двух одиночек), teh-led — к южной кромке линзы,
        // teh-sklad — к паллете у купола-тоннеля, где уже лежит груз.
        //
        // Побочный и главный по числам эффект: teh-dom1 держал ЛЕВУЮ кромку
        // кадра (u -0.94) — дальше любой постройки жилого квартала. Ровер,
        // который нечего было делать на пустом грунте, стоил всей колонии
        // 1.2 м экранного размаха.
        // КРУГ 27, находка 1. Тот же несинхронный переезд, что у груза фермы:
