        // klin-v ПЕРЕЕХАЛ в клин между причалом и жильём и стал членом кучки
        // «gruz-klin» (круг 8, пункт 5, тяжесть 2: «одиночные тёмно-серые
        // кубические ящики стоят поодиночке прямо на голом грунте»; свод §8:
