        // кромки кадра, то есть предмет не работал вовсе.
        new object[] { "dekor-04", 1.4f, -11.4f, 2.2f, 0f, 0.05f, 0f, 6, "gruz-klin" },

        // ===== ЮЖНЫЙ ПРОВАЛ КАДРА: ЧЕТЫРЕ ПОСЛЕДНИХ СВОБОДНЫХ ГНЕЗДА =====
        //
        // Круг 4, пункты 1 и 4 (тяжесть 1): «весь низ левой половины кадра»
        // голый. Скан всей видимой части плато (шаг 0.75 м, радиус до 28.5 м,
        // экранные координаты |u| <= 0.95 и |v| <= 0.90) после каймы и клина
        // нашёл ровно ЧЕТЫРЕ места, где предмет 3.4 м ещё встаёт с зазором
        // 2.0 м и больше. Три из них лежат в южном провале между героем,
