        // ===== ЦЕПЬ «ДОБЫЛ — ПРИВЁЗ — ПЕРЕРАБОТАЛ», КРУГ 6 =====
        //
        // Пункты 2 и 8 (тяжесть 1 и 2): «между буровой карьера и ближайшей
        // мастерской нет ни одного видимого груза, повозки или трубы вдоль
        // дороги», «у склада с силосами ни у подножия, ни на подходящих
        // дорогах нет ни одной кучи материала или гружёной техники». Свод,
        // раздел 4: промежуток между блоками у эталонов НИКОГДА не пуст —
        // там дорога, труба или груз.
        //
        // Обе цепочки положены НА уже существующие явные ответвления дорожной
        // сети (см. Otvetvlenie в BuildRoadStrips): руда идёт burovaya-04 ->
        // sklad-bunkery, вода — burovaya-05 -> kupol-tunnel жилого квартала.
        // Координаты взяты долями вдоль этих двух отрезков, шаг 2.5-3.0 м
        // (1-1.2 клетки при требовании пункта 2 в 2-3 клетки — шаг мельче,
