        //
        // Правило, которое из этого следует и которого раньше нигде не было
        // записано: груз между двумя кластерами обязан лежать НЕ на оси, а
        // сбоку от неё — так, чтобы по одной из двух осей выйти за габарит
        // обоих соседей. Условие пересечения в разводке требует перекрытия
        // ПО ОБЕИМ осям сразу, поэтому достаточно разойтись по одной.
        //
        // Числа посчитаны от фактических полугабаритов: буровая карьера
        // 2.2 x 2.3, силосный склад 2.6 x 2.7, ящик 1.1, зазор поставленного
        // груза 0.15. Запретный прямоугольник буровой — 3.45 по x и 3.55 по z,
