        new object[] { "dekor-04", 7f, 22f, 2f, 90f, 0f, 0f, 6, "ruda-voz1" },
        // ПЕРЕНОСЧИК ГРУЗА, круг 8, пункт 3 (тяжесть 1): «нет ни одного
        // видимого переносчика груза — ни гружёной повозки, ни конвейера...
        // игрок не может прочитать глазами, куда девается добытый ресурс».
        // Правка оценщика допускает минимум: «поставить на этом пути гружёный
