        // КРУГ 1 (ориентация): 270 -> 90. Подъем 2.3 и связка не тронуты, зазор над штабелем тот же.
        // КРУГ 10, пункт 2 (тяжесть 1): «дорога от карьера до ближайшего
        // склада — голое полотно без единой трубы, вагонетки или груза руды
        // между карьером и любым другим зданием». Труба вдоль этой ветки
