        // ставится здесь же и ИМЕННО НА НЕЙ, а не рядом.
        // Ветка идёт от burovaya-04 (мир 10.0, 25.5 после стяжки карьера) к
        // sklad-bunkery (мир 4.0, 18.0). Две точки взяты на трети и двух
        // третях отрезка со сдвигом 0.6 м вбок от оси, чтобы груз стоял У
        // полотна, а не в колее: (8.0, 23.0) и (6.0, 20.5). Зона 6 выбрана
        // намеренно — груз в промежутке между кластерами не должен раздвигать
        // кадр (VpisatKadr пустошь не считает).
        // КРУГ 27, третий проход. Замер: в коробке 13x7 м между буровой и
