        // связками, из которых две одночленные. На кадре это вышло россыпью
        // одинаковых серых кубов на голом грунте, то есть ровно тем дефектом,
        // который этот же круг чинит в жилом квартале (находка 3, доктрина 5.2
        // «кучками по 2-5, а не поштучно»).
        // Все четыре сведены в ОДНУ связку и в один штабель у восточной,
