        // sklad-gruz: свод §8 просит штабель 3-6 ящиков, здесь их шесть на
        // пятне 4x4 м. Связка общая намеренно — она же держит их вместе
        // против разводки.
        // КРУГ 5, находка 3 (тяжесть 2): «тёмно-серые грузовые ящики
        // выстроены почти правильной сеткой 3x3-4, все одного размера, ряды и
