        // Правка оценщика: «разбить каждую сетку на 2-3 кучки по 2-4 ящика, в
        // каждой смешать один крупный штабель с 1-2 мелкими, довернуть часть
        // ящиков на 10-20 градусов от прямого угла сетки».
        //
        // Четыре предмета одной связки стояли квадратом 1.6 x 2.8 м с
        // поворотами 90/0/270/90 — то есть ровно решёткой. Стало две кучки по
        // два предмета, разнесённые на 3.0 м, в каждой крупный плюс мелкий
